# Source for q/spi-doppler4.js: SPI Doppler + Hemodynamics fourth batch (equation practice, color/power modes, flow physics).
D="Doppler"; H="Hemodynamics"
Q=[
# --- Doppler equation practice ---
(D,"Transmitted frequency 2 MHz, blood velocity 1 m/s, angle 0°. The Doppler shift is about:","2.6 kHz",["1.3 kHz","5.2 kHz","260 Hz"],"Δf = 2 × 2,000,000 × 1 ÷ 1540 ≈ 2,597 Hz.","C"),
(D,"Transmitted frequency 4 MHz, velocity 0.5 m/s, angle 0°. The Doppler shift is about:","2.6 kHz",["1.3 kHz","5.2 kHz","10 kHz"],"Doubling frequency and halving velocity give the same shift.","C"),
(D,"Transmitted frequency 2 MHz, velocity 1 m/s, angle 60°. The Doppler shift is about:","1.3 kHz",["2.6 kHz","0 Hz","5.2 kHz"],"cos 60° = 0.5, so the shift is half the 0° value.","C"),
(D,"A Doppler shift of 1.3 kHz is measured at 2.5 MHz and 0°. Blood velocity is about:","0.4 m/s",["1.0 m/s","4.0 m/s","0.04 m/s"],"v = 1300 × 1540 ÷ (2 × 2,500,000) ≈ 0.40 m/s.","C"),
(D,"The cosine of 30° is about:","0.87",["0.5","0.71","1.0"],"cos 0° = 1, cos 45° ≈ 0.71, cos 60° = 0.5, cos 90° = 0.","F"),
(D,"The cosine of 45° is about:","0.71",["0.87","0.5","0"],"At 45°, the measured shift is about 71% of the true value.","F"),
(D,"Blood velocity doubles while all else stays the same. The Doppler shift:","Doubles",["Halves","Stays the same","Quadruples"],"Shift is directly proportional to velocity.","F"),
(D,"Doppler shifts in clinical imaging usually fall in the range of:","Audible sound (about 20 Hz to 20 kHz)",["Megahertz","Ultrasound above 1 MHz","Below 1 Hz"],"That is why Doppler signals can be heard through speakers.","F"),
(D,"A small error in angle correction causes the largest velocity error at:","Large angles such as 60° or more",["0°","10°","Errors are the same at all angles"],"The cosine changes fastest at larger angles.","C"),
(D,"Flow toward the transducer produces:","A positive Doppler shift (received frequency higher than transmitted)",["A negative shift","No shift","A shift only at 90°"],"Flow away gives a negative shift.","F"),
(D,"PRF 10 kHz. The Nyquist limit is:","5 kHz",["10 kHz","20 kHz","2.5 kHz"],"Nyquist = PRF ÷ 2.","F"),
(D,"A Doppler shift of 4 kHz with a PRF of 6 kHz will:","Alias, because 4 kHz is above the 3 kHz Nyquist limit",["Not alias","Disappear","Double in size"],"Raise the PRF, lower the frequency, shift the baseline or use CW.","C"),
(D,"Red blood cells scatter ultrasound by Rayleigh scattering. If frequency doubles, scattered intensity increases about:","16 times",["2 times","4 times","No change"],"Rayleigh scattering increases with frequency to the fourth power.","C"),
# --- Color, power and filters ---
(D,"Power (energy) Doppler displays:","The strength (amplitude) of the Doppler signal, not velocity or direction",["Velocity and direction","Peak velocity","Only aliasing"],"It is very sensitive to slow and low-volume flow.","F"),
(D,"An advantage of power Doppler over color velocity Doppler is that it:","Does not alias and is less angle dependent",["Shows direction","Has a high frame rate","Shows peak velocity"],"Directional power Doppler is available on some systems.","F"),
(D,"A disadvantage of power Doppler is that it:","Is very sensitive to flash artifact from tissue or probe motion",["Aliases easily","Shows too much direction","Cannot detect slow flow"],"It also has a low frame rate.","F"),
(D,"A burst of color over a large area during heart or breathing motion is called:","Flash artifact",["Aliasing","Mirror image","Twinkling"],"Raising the wall filter or asking the patient to hold still helps.","F"),
(D,"Twinkling artifact appears as:","Rapidly changing color behind a rough, strongly reflecting surface such as a stone or calcium",["Smooth laminar flow","A mirror image","Absent color"],"It can help find small stones or calcifications.","C"),
(D,"Color bleeding (blooming) beyond vessel walls is reduced by:","Lowering the color gain",["Raising the color gain","Lowering the wall filter","Increasing persistence"],"Set gain just below the level where noise appears.","F"),
(D,"Setting the wall filter too high can cause:","Loss of low-velocity flow, such as diastolic flow, making a vessel look high-resistance",["Aliasing","Mirror images","More noise"],"Use the lowest wall filter that removes wall thump.","F"),
(D,"Color Doppler can show flow direction better than spectral Doppler for a whole area because:","It maps mean velocity and direction across many locations at once",["It shows peak velocity","It never aliases","It uses CW"],"Spectral Doppler shows detail at one location.","F"),
(D,"A larger color 'ensemble' (more pulses per line) improves:","Accuracy and sensitivity of color, but lowers frame rate",["Frame rate","Axial resolution","Penetration only"],"Fewer pulses give a faster but noisier image.","F"),
(D,"Color 'smoothing' and persistence in color Doppler make the image:","Smoother but can blur fast flow events",["Sharper in time","Faster","Free of aliasing"],"Use low persistence for brief cardiac jets.","F"),
(D,"When flow is exactly perpendicular to the beam, color Doppler shows:","No color, even though blood is moving",["Bright aliasing","A mosaic","Mirror artifact"],"Change the beam angle to see flow.","F"),
(D,"The time-averaged peak velocity (TAPV) over a cardiac cycle is useful for calculating:","Flow volume in a vessel",["Wall thickness","Heart rate","Frame rate"],"Flow = mean velocity × area.","C"),
(D,"Spectral Doppler intensity at a given velocity represents:","How many red cells are moving at that velocity",["The depth of the vessel","The angle","The PRF"],"Bright areas mean many cells at that speed.","F"),
(D,"Duplex imaging means:","Showing 2D imaging and Doppler information together",["Using two transducers","Imaging two patients","Using only CW"],"Triplex adds color to 2D and spectral Doppler.","F"),
(D,"Which Doppler mode usually has the highest temporal-average intensity at the focus?","Pulsed wave spectral Doppler",["B-mode","M-mode","Color Doppler always"],"Keep Doppler time short (ALARA).","C"),
(D,"In spectral Doppler, a 'window' under the envelope means:","Most red cells are moving at similar speeds (laminar flow)",["Turbulent flow","No flow","Aliasing"],"Turbulence fills in the window.","F"),
(D,"Venous Doppler is best performed with:","A low PRF (scale) and low wall filter",["The highest scale","A high wall filter","CW only"],"Venous flow is slow.","F"),
(D,"Moving the PW gate deeper makes aliasing more likely because:","The maximum PRF falls, lowering the Nyquist limit",["The Doppler shift rises","The wall filter rises","The transducer frequency doubles"],"Deeper gates need more listening time between pulses.","C"),
# --- Hemodynamics: resistance and flow ---
(H,"Flow through a vessel equals:","Pressure difference ÷ resistance",["Pressure × resistance","Velocity × resistance","Resistance ÷ pressure"],"This is like Ohm's law in electricity.","F"),
(H,"Two vessels in series have resistances of 2 and 3 units. Total resistance is:","5 units",["1.2 units","6 units","1 unit"],"In series, resistances add.","F"),
(H,"Two vessels in parallel each have resistance of 6 units. Total resistance is:","3 units",["12 units","6 units","36 units"],"1/R = 1/6 + 1/6 = 1/3, so R = 3.","C"),
(H,"Adding more parallel vessels to a circulation makes total resistance:","Lower",["Higher","Unchanged","Infinite"],"This is why total capillary resistance is lower than each capillary's own resistance.","F"),
(H,"If vessel radius is halved, resistance (by Poiseuille's law) increases by:","16 times",["2 times","4 times","8 times"],"Resistance is proportional to 1 ÷ r⁴.","C"),
(H,"Doubling vessel length (with all else equal) makes resistance:","Double",["Halve","Stay the same","Increase 16 times"],"Resistance is directly proportional to length.","F"),
(H,"Doubling blood viscosity makes resistance:","Double",["Halve","Stay the same","Increase 16 times"],"Higher hematocrit increases viscosity.","F"),
(H,"Blood viscosity is mainly increased by:","A higher hematocrit (more red cells)",["Lower red cell count","Higher temperature","Faster flow only"],"Polycythemia makes blood thicker.","F"),
# --- Continuity and Bernoulli ---
(H,"If the diameter of a tube is halved, with the same flow, velocity becomes:","4 times higher",["2 times higher","Half","The same"],"Area falls to one-quarter.","C"),
(H,"A 50% diameter stenosis reduces cross-sectional area by about:","75%",["50%","25%","90%"],"Area depends on diameter squared: 0.5² = 0.25.","C"),
(H,"A 70% diameter stenosis reduces area by about:","91%",["70%","49%","30%"],"0.3² = 0.09, so 91% area reduction.","C"),
(H,"According to the Bernoulli principle, at the narrowest part of a stenosis:","Velocity is highest and pressure is lowest",["Velocity is lowest and pressure highest","Both are highest","Both are lowest"],"Energy changes from pressure to kinetic.","F"),
(H,"A stenosis usually becomes hemodynamically significant (reducing flow or pressure) at about:","50% diameter reduction (about 75% area)",["10% diameter reduction","90% area reduction only","Any narrowing"],"The exact level depends on flow demand.","F"),
# --- Flow profiles ---
(H,"In laminar parabolic flow, mean velocity equals about:","Half of the peak (centerline) velocity",["The same as peak velocity","Twice peak velocity","Zero"],"Plug flow has a mean velocity close to peak.","C"),
(H,"Plug flow is typical in:","Large vessels near the start, such as the ascending aorta",["Small capillaries","Long narrow veins","Distal arteries"],"Flow becomes parabolic further along.","F"),
(H,"The Reynolds number above which turbulence usually begins is about:","2,000",["20","200,000","2"],"Turbulence becomes more likely with higher velocity and diameter.","F"),
(H,"The Windkessel effect describes:","The aorta stretching in systole and recoiling in diastole to keep blood flowing",["Blood clotting","Valve closure","Capillary leakage"],"Stiff arteries lose this effect, raising systolic pressure.","F"),
(H,"A triphasic waveform is typical of:","High-resistance peripheral arteries at rest, such as leg arteries",["Organ arteries such as the kidney","Veins","Capillaries"],"Forward flow, brief reversal, then small forward flow.","F"),
(H,"Low-resistance waveforms with continuous forward diastolic flow are found in vessels supplying the:","Brain, kidneys and liver",["Resting leg muscles","Resting arm muscles","Skin only"],"These organs need constant blood flow.","F"),
(H,"After a meal, the superior mesenteric artery waveform changes from:","High resistance to low resistance",["Low resistance to high resistance","Continuous to absent","Arterial to venous"],"Gut vessels dilate to absorb food.","C"),
(H,"With exercise, leg artery waveforms usually:","Become low resistance with more diastolic flow",["Become more triphasic","Show no flow","Reverse completely"],"Muscle arteries dilate to deliver more blood.","F"),
(H,"A high-resistance 'thump' signal just before a blockage suggests:","Flow is hitting an occlusion downstream",["Normal flow","A low-resistance organ","Venous flow"],"Distal to the blockage, flow may be tardus parvus.","F"),
(H,"In subclavian steal, the flow in the vertebral artery on the affected side is:","Reversed (going down instead of up)",["Normal","Absent","Faster upward"],"Blood is 'stolen' from the brain to supply the arm.","C"),
# --- Pressure and energy ---
(H,"The three main forms of energy in flowing blood are:","Pressure, kinetic and gravitational (potential) energy",["Electrical, chemical and nuclear","Heat, light and sound","Magnetic only"],"Energy is lost through viscous, frictional and inertial losses.","F"),
(H,"Hydrostatic pressure at the ankle in a standing adult is about:","100 mmHg",["0 mmHg","10 mmHg","500 mmHg"],"It depends on the height of the column of blood above the point.","C"),
(H,"Hydrostatic pressure is zero at the level of the:","Heart (right atrium)",["Feet","Head","Abdomen"],"Points above the heart have negative hydrostatic pressure.","F"),
(H,"Veins can hold large volumes at low pressure because they have:","High compliance (capacitance)",["Thick walls","High resistance","No valves"],"Most of the blood volume is in the veins.","F"),
(H,"Venous valves in the legs:","Keep blood flowing toward the heart and prevent backflow",["Block flow to the heart","Are found only in the arms","Do not exist"],"Incompetent valves cause reflux and varicose veins.","F"),
(H,"When a standing patient contracts the calf muscle, leg venous flow:","Increases toward the heart",["Stops completely","Reverses","Does not change"],"This 'muscle pump' helps return blood.","F"),
(H,"During Valsalva strain, flow in the leg veins:","Decreases or stops",["Increases greatly","Becomes pulsatile","Reverses in normal veins for a long time"],"Raised abdominal pressure blocks venous return. Reflux on Valsalva suggests incompetent valves.","F"),
(H,"Frictional energy loss in blood flow turns energy into:","Heat",["Sound only","Pressure","Light"],"Energy is always lost as blood flows through vessels.","C"),
(H,"Pulsatile flow differs from steady flow because:","Velocity and pressure change with each heartbeat",["It never changes","It occurs only in veins","It has no pressure"],"Arterial flow is pulsatile.","F"),
(H,"Capillaries have slow flow mainly because:","Their total cross-sectional area is very large",["They are long","Their pressure is high","Blood is thicker there"],"Slow flow allows exchange of oxygen and nutrients.","F"),
]
